GLIBC_2.17 {
    global:
        *;
};

GLIBC_2.34 {
    global:
        pthread_cancel;
        pthread_create;
        pthread_testcancel;
        pthread_spin_trylock;
        pthread_spin_lock;
        aio_cancel;
        aio_error;
        aio_fsync;
        aio_read;
        aio_return;
        aio_suspend;
        aio_write;
        mq_unlink;
        pthread_barrier_destroy;
        pthread_barrier_init;
        pthread_barrier_wait;
        pthread_join;
        pthread_kill;
        pthread_mutex_getprioceiling;
        pthread_mutex_trylock;
        pthread_mutexattr_destroy;
        pthread_mutexattr_gettype;
        pthread_mutexattr_init;
        pthread_mutexattr_setpshared;
        pthread_mutexattr_settype;
        pthread_rwlock_destroy;
        pthread_rwlock_init;
        pthread_rwlock_rdlock;
        pthread_rwlock_unlock;
        pthread_rwlock_wrlock;
        pthread_setschedprio;
        sem_destroy;
        sem_init;
        sem_open;
        sem_timedwait;
        sem_unlink;
        sem_wait;
        shm_open;
        shm_unlink;
} GLIBC_2.17;

/* Debian RISC-V glibc toolchains version selected POSIX APIs at 2.27, while
 * the AArch64 toolchain uses 2.17. Export the interposers at the newer node
 * so both target ABIs resolve the preload. */
GLIBC_2.27 {
    global:
        clock;
        catopen;
        catgets;
        catclose;
        sleep;
        pthread_setcanceltype;
        pthread_exit;
        fork;
        waitpid;
        __register_atfork;
        pthread_attr_init;
        pthread_attr_setscope;
        pthread_attr_getscope;
        pthread_attr_setschedparam;
        pthread_attr_setschedpolicy;
        pthread_attr_getschedpolicy;
        pthread_attr_getschedparam;
        pthread_attr_destroy;
        pthread_cond_init;
        pthread_cond_wait;
        pthread_cond_timedwait;
        pthread_cond_broadcast;
        pthread_cond_signal;
        pthread_cond_destroy;
        pthread_getschedparam;
        sched_getparam;
        sched_setparam;
        sched_setscheduler;
        sched_getscheduler;
        sched_get_priority_max;
        sched_get_priority_min;
        pthread_mutex_init;
        pthread_mutex_lock;
        pthread_mutex_unlock;
        pthread_setschedparam;
        pthread_mutex_destroy;
        sigaction;
        sigset;
        kill;
        sigqueue;
        getuid;
        geteuid;
        setuid;
        setpwent;
        getpwent;
        endpwent;
        seteuid;
        sysconf;
        mlock;
        munlock;
        mlockall;
        munlockall;
        msync;
        mmap;
        munmap;
        open;
} GLIBC_2.17;
